{
  "findings": [
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 Bucket has an ACL defined which allows public READ access.",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "CRITICAL",
      "explanation": "The ACL for the S3 bucket is set using a variable, which could potentially allow public READ access. This poses a risk of exposing sensitive data if the variable is misconfigured."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"bucket_2\" {\n  bucket = \"roger-bucket-2\"\n  acl    = \"private\"\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        kms_master_key_id = aws_kms_key.my_key.arn\n        sse_algorithm     = \"aws:kms\"\n      }\n    }\n  }\n}",
  "fix_summary": "Replaced the variable-based ACL with a fixed value of \"private\" to ensure the bucket does not allow public READ access."
}
